def preserve_legacy(apps, schema_editor):
    import json
    from datetime import timedelta
    from django.core.serializers.json import DjangoJSONEncoder

    db = schema_editor.connection.alias
    Archive = apps.get_model("songs", "LegacyRecord")

    def save(kind, pk, data):
        Archive.objects.using(db).create(
            kind=kind,
            original_id=pk,
            data=json.loads(json.dumps(data, cls=DjangoJSONEncoder)),
        )

    for name in (
        "Bid",
        "BidResult",
        "BiddingRound",
        "CompetitionPhase",
        "PeerReviewAllocation",
        "PeerReview",
    ):
        for row in apps.get_model("songs", name).objects.using(db).values():
            save(name, row["id"], row)
    for row in (
        apps.get_model("users", "UserProfile").objects.using(db).values("id", "token")
    ):
        save("UserTokens", row["id"], {"token": row["token"]})
    Chart = apps.get_model("songs", "Chart")
    Song = apps.get_model("songs", "Song")
    charts = list(Chart.objects.using(db).all())
    by_id = {chart.pk: chart for chart in charts}
    songs = {song.pk: song for song in Song.objects.using(db).all()}
    for chart in charts:
        # Preserve old metadata independently before dropping legacy columns.
        old = Chart.objects.using(db).filter(pk=chart.pk).values().get()
        save("Chart", chart.pk, old)
        base = by_id.get(chart.part_one_chart_id)
        contributor_ids = {chart.user_id}
        if base:
            contributor_ids.add(base.user_id)
        chart.contributors.add(*contributor_ids)
        chart.legacy_metadata = {
            key: old[key]
            for key in (
                "bidding_round_id",
                "bid_result_id",
                "completion_bid_result_id",
                "part_one_chart_id",
                "is_part_one",
                "status",
            )
        }
        chart.legacy_metadata["contributor_ids"] = sorted(contributor_ids)
        chart.title = (
            songs[chart.song_id].title if chart.song_id in songs else "未命名谱面"
        )
        chart.source_song_id = chart.song_id
        chart.status = "archived" if chart.status == "part_submitted" else "submitted"
        chart.submission_key = uuid.uuid4()
        chart.net_sync_status = "unknown"
        chart.net_sync_error = "历史上传，请先核对 Net 上的文件"
        chart.save(using=db)
    Review = apps.get_model("songs", "PeerReview")
    # Keep the latest score; every superseded row remains in LegacyRecord.
    seen = set()
    for review in Review.objects.using(db).order_by("-created_at", "-id"):
        pair = (review.reviewer_id, review.chart_id)
        if pair in seen:
            review.delete(using=db)
        else:
            seen.add(pair)
            if review.comment is None:
                review.comment = ""
                review.save(using=db, update_fields=["comment"])
    Phase = apps.get_model("songs", "CompetitionPhase")
    for phase in Phase.objects.using(db).all():
        # Old two-stage schedules become history, never new submission restrictions.
        phase.kind = "display"
        if phase.end_time <= phase.start_time:
            phase.end_time = phase.start_time + timedelta(seconds=1)
        phase.save(using=db)


